// main.c — Example C application using Thryve FFI library
//
// This example demonstrates how to create a plugin and observer
// using the Thryve FFI layer from C.
//
// Build with CMake or manually:
//   gcc -std=c11 -I<OUT_DIR> main.c -L<LIB_DIR> -lthryve_ffi -o thryve_example
//
// <OUT_DIR> is the directory containing thryve.h (generated by cbindgen)
// <LIB_DIR> is the directory containing thryve_ffi.dll (Windows) or libthryve_ffi.so (Linux)

#include "thryve.h"  // C-compatible header (generated by cbindgen)

#include <stdio.h>
#include <stdlib.h>

// ============================================================================
// Plugin Implementation
// ============================================================================

// Plugin cleanup function — called when the plugin is being freed
void my_plugin_cleanup(const void* core_ptr) {
    printf("Plugin cleanup called\n");
}

// Plugin entry point — called when the plugin's task is executed
FfiTaskResult my_plugin_entry_point(void) {
    printf("Plugin entry point called\n");
    
    // Use the helper function to create a result with proper fields
    FfiTaskResult result = ffi_task_result_new("Success", "Plugin executed", "Main");
    // Or construct manually:
    // FfiTaskResult result = {0};
    // result.result_type = "Success";
    // result.message = "Plugin executed";
    // result.log_file = "Main";
    return result;
}

// ============================================================================
// Observer Implementation
// ============================================================================

// Observer cleanup function — called when the observer is being freed
void my_observer_cleanup(const void* core_ptr) {
    printf("Observer cleanup called\n");
}

// Observer job function — called when the observer runs
void my_observer_job(FfiObserver observer) {
    printf("Observer job called\n");
}

// ============================================================================
// Task Job Implementation
// ============================================================================

FfiTaskResult my_task_job(void) {
    printf("Task job called\n");
    
    FfiTaskResult result = {0};
    return result;
}

// ============================================================================
// Main Function
// ============================================================================

int main(void) {
    printf("=== Thryve FFI Example ===\n");

    // 1. Create configuration
    FfiConfig config = ffi_config_default();
    if (!config) {
        fprintf(stderr, "Failed to create config\n");
        return 1;
    }
    printf("Config created\n");

    // 2. Create PacketHandle from configuration (required for plugins/observers)
    FfiPacketHandle packet_handle = ffi_packet_handle_create(config);
    if (!packet_handle) {
        fprintf(stderr, "Failed to create packet handle\n");
        ffi_config_free(config);
        return 1;
    }
    printf("PacketHandle created\n");

    // 3. Create context from configuration
    FfiCtx ctx = ffi_ctx_create(config);
    if (!ctx) {
        fprintf(stderr, "Failed to create context\n");
        ffi_packet_handle_free(packet_handle);
        ffi_config_free(config);
        return 1;
    }
    printf("Context created\n");

    // 4. Create a plugin
    FfiPlugin plugin = ffi_plugin_create(
        "MyPlugin",           // name
        "MyType",             // type
        NULL,                 // plg_core_ptr (opaque pointer)
        packet_handle,        // tx (packet handle - REQUIRED)
        my_plugin_cleanup,    // clean_up callback
        my_plugin_entry_point // entry_point callback
    );
    
    if (!plugin) {
        fprintf(stderr, "Failed to create plugin\n");
        ffi_packet_handle_free(packet_handle);
        ffi_ctx_free(ctx);
        ffi_config_free(config);
        return 1;
    }
    printf("Plugin created\n");

    // 5. Add plugin to context (takes ownership of the plugin)
    FfiStatus status = ffi_ctx_add_plugin(ctx, plugin);
    if (status != FfiStatus_Ok) {
        fprintf(stderr, "Failed to add plugin to context: %d\n", status);
        ffi_plugin_free(plugin);
        ffi_packet_handle_free(packet_handle);
        ffi_ctx_free(ctx);
        ffi_config_free(config);
        return 1;
    }
    printf("Plugin added to context\n");

    // 6. Create an observer
    FfiObserver observer = ffi_observer_create(
        "MyObserver",         // name
        "MyType",             // type
        NULL,                 // obs_core_ptr (opaque pointer)
        packet_handle,        // tx (packet handle - REQUIRED)
        my_observer_cleanup,  // clean_up callback
        my_observer_job       // obs_job callback
    );
    
    if (!observer) {
        fprintf(stderr, "Failed to create observer\n");
    } else {
        printf("Observer created\n");
        
        // Add observer to context
        status = ffi_ctx_add_observer(ctx, observer);
        if (status != FfiStatus_Ok) {
            fprintf(stderr, "Failed to add observer to context: %d\n", status);
        } else {
            printf("Observer added to context\n");
        }
    }

    // 7. Create a task
    FfiTask task = ffi_task_create(
        "MyTask",             // name
        0,                    // priority
        my_task_job           // job callback
    );
    
    if (!task) {
        fprintf(stderr, "Failed to create task\n");
    } else {
        printf("Task created\n");
        
        // Send the task to the context
        status = ffi_ctx_send_task(ctx, task);
        if (status != FfiStatus_Ok) {
            fprintf(stderr, "Failed to send task: %d\n", status);
        } else {
            printf("Task sent to context\n");
        }
        
        ffi_task_free(task);
    }

    // 8. Start the engine (interactive mode)
    printf("\nStarting interactive engine...\n");
    printf("Press Enter to stop...\n");
    
    FfiRunHandle handle = ffi_run_interactive_start(ctx);
    if (handle) {
        // Wait for user input to stop
        getchar();
        
        // Stop the engine
        ffi_run_interactive_free(handle);
    }

    // 9. Cleanup
    // Note: plugin and observer are owned by ctx, so don't free them
    ffi_packet_handle_free(packet_handle);
    ffi_ctx_free(ctx);
    ffi_config_free(config);

    printf("\n=== Example finished ===\n");
    return 0;
}
